"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/team/variants/01-panels";
const variants = {"panels":View0};
export interface ArtemisTeamProps { className?: string; variant?: "panels"; }
export function ArtemisTeam({ className, variant = "panels" }: ArtemisTeamProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { artemisDemoAvatar } from "../../../lib/demo-avatar";
import { motion, useReducedMotion } from "motion/react";
import { useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_SWAP } from "../../../lib/ease";
type Member = {
    slug: string;
    name: string;
    role: string;
    bio: string;
    photo: string;
};
const MEMBERS: Member[] = [
    {
        slug: "jordan-blake",
        name: "Jordan Blake",
        role: "Founder & CEO",
        bio: "Sets the vision and keeps the bar high. Spent a decade leading design systems teams.",
        photo: artemisDemoAvatar("member-1"),
    },
    {
        slug: "jamie-reed",
        name: "Jamie Reed",
        role: "Head of Engineering",
        bio: "Owns the registry and runtime, and treats motion as a feature, not a finish.",
        photo: artemisDemoAvatar("member-2"),
    },
    {
        slug: "casey-ellis",
        name: "Casey Ellis",
        role: "Design Lead",
        bio: "Tunes every spring and easing curve until it feels physical.",
        photo: artemisDemoAvatar("member-3"),
    },
    {
        slug: "morgan-wells",
        name: "Morgan Wells",
        role: "Developer Advocate",
        bio: "Turns complex APIs into docs people actually enjoy reading.",
        photo: artemisDemoAvatar("member-4"),
    },
    {
        slug: "riley-park",
        name: "Riley Park",
        role: "Staff Engineer",
        bio: "Performance obsessive who ships at 60fps or not at all.",
        photo: artemisDemoAvatar("member-5"),
    },
];
const GROW_SPRING = { type: "spring", stiffness: 232, damping: 37.5, mass: 1 } as const;
const DETAIL_IN = { ...ARTEMIS_SPRING_SWAP, delay: 0.08 } as const;
const DETAIL_OUT = { duration: 0.15, ease: ARTEMIS_EASE_OUT } as const;
const INSTANT = { duration: 0 } as const;
const LI_BASE = "art:group art:relative art:min-h-0 art:min-w-0 art:overflow-hidden art:rounded-3xl art:border art:bg-muted art:transition-colors art:duration-300 art:has-[:focus-visible]:ring-2 art:has-[:focus-visible]:ring-ring art:has-[:focus-visible]:ring-offset-2 art:has-[:focus-visible]:ring-offset-background";
const IMG_BASE = "art:absolute art:inset-0 art:size-full art:object-cover art:object-[50%_25%] art:transition-[transform,filter] art:duration-700";
const BUTTON_CLASS = "art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:absolute art:inset-0 art:size-full art:outline-none art:rounded-full";
const LINK_CLASS = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:hover:border-border art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:relative art:z-10 art:mt-3 art:h-8 art:gap-1 art:bg-white/15 art:px-3 art:text-xs art:text-white art:backdrop-blur-sm art:hover:bg-white/25 art:rounded-full";
function Panel({ member, active, reduce, onActivate, }: {
    member: Member;
    active: boolean;
    reduce: boolean;
    onActivate: () => void;
}) {
    const detail = reduce
        ? { opacity: active ? 1 : 0, transition: INSTANT }
        : active
            ? { opacity: 1, y: 0, transition: DETAIL_IN }
            : { opacity: 0, y: 10, transition: DETAIL_OUT };
    return (<motion.li className={`${LI_BASE} ${active ? "art:border-foreground/15" : "art:border-border"}`} style={{ flexBasis: "0" }} initial={false} animate={{ flexGrow: active ? 3.4 : 1 }} transition={reduce ? INSTANT : GROW_SPRING} onMouseEnter={onActivate} onClick={onActivate}>
      <img src={member.photo} alt="" loading="lazy" className={`${IMG_BASE} ${active ? "art:scale-100 art:grayscale-0" : "art:scale-105 art:grayscale-[0.85] art:brightness-90"}`} style={{ transitionTimingFunction: "cubic-bezier(0.16, 1, 0.3, 1)" }}/>
      <div aria-hidden="true" className="art:absolute art:inset-0 art:bg-gradient-to-t art:from-black/85 art:via-black/25 art:to-transparent"/>
      <button type="button" className={BUTTON_CLASS} aria-label={`${member.name}, ${member.role}`} aria-expanded={active} onClick={onActivate} onFocus={onActivate}/>
      <div className="art:absolute art:inset-x-0 art:bottom-0 art:p-5">
        <motion.div aria-hidden={!active} className={active ? "art:mb-4 art:w-64 art:max-w-full" : "art:mb-4 art:w-64 art:max-w-full art:pointer-events-none"} initial={false} animate={detail}>
          <p className="art:text-pretty art:text-sm art:leading-6 art:text-white/85">{member.bio}</p>
          <a className={LINK_CLASS} href={`#${member.slug}`} tabIndex={active ? 0 : -1}>
            {"Profile"}
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-3.5" aria-hidden="true">
              <path d="M7 7h10v10"/>
              <path d="M7 17 17 7"/>
            </svg>
          </a>
        </motion.div>
        <p className="art:truncate art:text-base art:font-medium art:text-white">{member.name}</p>
        <p className="art:truncate art:text-xs art:text-white/70">{member.role}</p>
      </div>
    </motion.li>);
}
export default function TeamPanels() {
    const [active, setActive] = useState(0);
    const reduce = useReducedMotion() === true;
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:mx-auto art:w-full art:max-w-6xl">
            <div className="art:mx-auto art:max-w-xl art:text-center">
              <span className="art:inline-flex art:items-center art:rounded-full art:bg-muted art:px-3 art:py-1 art:text-xs art:font-medium art:text-muted-foreground art:shadow-[inset_0_1px_3px_rgba(0,0,0,0.06)]">
                {"Team"}
              </span>
              <h2 className="art:mt-5 art:text-balance art:text-4xl art:font-medium art:text-foreground">
                {"Meet the makers."}
              </h2>
              <p className="art:mx-auto art:mt-4 art:max-w-md art:text-pretty art:text-sm art:leading-7 art:text-muted-foreground">
                {"Hover or tap a panel to meet the people behind every component."}
              </p>
            </div>
            <ul className="art:mt-12 art:flex art:h-[38rem] art:flex-col art:gap-2.5 art:@min-[768px]/artemis:h-[28rem] art:@min-[768px]/artemis:flex-row">
              {MEMBERS.map((member, i) => (<Panel key={member.slug} member={member} active={active === i} reduce={reduce} onActivate={() => setActive(i)}/>))}
            </ul>
          </div>
        </section>
      </div>
    </>);
}

// @zeus-internal
const avatars = ["/assets/artemis/a5badc559b706aa529b9.svg", "/assets/artemis/327d06eee6b741023403.svg", "/assets/artemis/83b960a1aaa67c851088.svg"];
export function artemisDemoAvatar(key: string) {
  const index = Array.from(key).reduce((sum, char) => sum + char.charCodeAt(0), 0);
  return avatars[index % avatars.length];
}
